toolArgs.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_193f0858e59a4bb08fc1c0c8bfe2f02f.Models
@namespace sv_193f0858e59a4bb08fc1c0c8bfe2f02f.Components.Pages.Apply

@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    @if (_submitted)
    {
        <div class="confirmation">
            <div class="confirmation-icon">&#10003;</div>
            <h2>Application Submitted!</h2>
            <p>Your application has been received. Your application ID is:</p>
            <strong class="application-id">#@_applicationId</strong>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="_currentStep" OnStepClicked="GoToStep" />

        @switch (_currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
                                  OnNext="HandlePersonalInfoNext" />
                break;
            case 1:
                <WorkHistoryStep Entries="_workEntries" OnNext="HandleWorkHistoryNext" OnBack="GoBack" />
                break;
            case 2:
                <ReferencesStep References="_references" OnNext="HandleReferencesNext" OnBack="GoBack" />
                break;
            case 3:
                <CoverLetterStep CoverLetter="@_coverLetter" OnNext="HandleCoverLetterNext" OnBack="GoBack" />
                break;
            case 4:
                <ReviewStep FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                            WorkEntries="_workEntries" References="_references" CoverLetter="@_coverLetter"
                            OnEdit="GoToStep" OnBack="GoBack" OnSubmit="HandleSubmit" />
                break;
        }
    }
</div>

@code {
    private int _currentStep;
    private bool _submitted;
    private int _applicationId;

    // Step 1
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2
    private List<WorkEntryForm.WorkEntryModel> _workEntries = new() { new() };

    // Step 3
    private List<ReferenceForm.ReferenceModel> _references = new() { new(), new() };

    // Step 4
    private string _coverLetter = "";

    private void HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoResult result)
    {
        _fullName = result.FullName;
        _email = result.Email;
        _phone = result.Phone;
        _address = result.Address;
        _currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkEntryForm.WorkEntryModel> entries)
    {
        _workEntries = entries;
        _currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> references)
    {
        _references = references;
        _currentStep = 3;
    }

    private void HandleCoverLetterNext(string coverLetter)
    {
        _coverLetter = coverLetter;
        _currentStep = 4;
    }

    private void GoToStep(int step)
    {
        if (step < _currentStep)
            _currentStep = step;
    }

    private void GoBack()
    {
        if (_currentStep > 0)
            _currentStep--;
    }

    private async Task HandleSubmit()
    {
        var workEntries = _workEntries.Select(e =>
            new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList();

        var references = _references.Select(r =>
            new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

        var application = new JobApplication(
            new PersonalInfo(_fullName, _email, _phone, _address),
            new WorkHistory(workEntries),
            references,
            _coverLetter
        );

        _applicationId = await ApplicationService.SubmitApplicationAsync(application);
        _submitted = true;
    }
}

